"""Test configuration module."""

from pathlib import Path

from pydantic import BaseModel, Field, field_validator

DEFAULT_TEST_MODELS = ["openai:gpt-4.1"]
DEFAULT_TESTS_FOLDER = "tests/"


class ComparisonConfig(BaseModel):
    """Tolerances applied when comparing the agent result to the expected data."""

    rtol: float = Field(default=1e-5, ge=0, description="Relative tolerance used to compare numeric values")
    atol: float = Field(default=1e-8, ge=0, description="Absolute tolerance used to compare numeric values")
    decimals: int = Field(default=2, ge=0, description="Decimals kept when rounding float values before comparing")


class TestConfig(BaseModel):
    """Defaults for `nao test`, each one overridable by the matching command line flag."""

    __test__ = False

    models: list[str] = Field(
        default_factory=lambda: list(DEFAULT_TEST_MODELS),
        description="The models to run the tests against, in the format 'provider:model_id'",
    )
    threads: int = Field(default=1, ge=1, description="Number of test runs to execute in parallel")
    select: list[str] = Field(
        default_factory=list,
        description="Test names, file stems or subfolders to run. Empty runs every discovered test",
    )
    folder: str = Field(default=DEFAULT_TESTS_FOLDER, description="Folder holding the test files")
    output_folder: str | None = Field(
        default=None, description="Folder where result files are written. Defaults to the outputs/ subfolder"
    )
    username: str | None = Field(default=None, description="Email used to authenticate against the nao backend")
    password: str | None = Field(default=None, description="Password used to authenticate against the nao backend")
    comparison: ComparisonConfig = Field(
        default_factory=ComparisonConfig, description="Tolerances used when comparing results to the expected data"
    )

    @field_validator("models")
    @classmethod
    def validate_models(cls, models: list[str]) -> list[str]:
        for model in models:
            provider, _, model_id = model.partition(":")
            if not provider or not model_id:
                raise ValueError(f"invalid model '{model}', expected the format 'provider:model_id'")
        return models

    @property
    def selection(self) -> str | None:
        """The `select` entries in the comma-separated form taken by the `--select` flag."""
        return ",".join(self.select) or None

    def tests_path(self, project_path: Path) -> Path:
        """Resolve the folder holding the test files."""
        return project_path / self.folder

    def outputs_path(self, project_path: Path) -> Path:
        """Resolve the folder where result files are written."""
        return project_path / (self.output_folder or f"{self.folder.rstrip('/')}/outputs")

